/* Dot-portrait data generated from 'Profile Pic.jpg': a 160x180 grid, row by row.
   data: two bytes per cell, [tone 1-255 (0 = empty), edge coverage 0-255].
   rgb:  the photo's own colour, three bytes per filled cell, in the same order.
   Loaded async; script.js rebuilds it as particles once it arrives. */
window.AH_PORTRAIT = { cols: 160, rows: 180, channels: 2, data: '', rgb: '' };
document.dispatchEvent(new Event('ah:portrait-data'));
